engine_core::assemble!(
    engine_gamebryo::units::funcs,
    engine_bs::units::funcs,
    engine_havok::units::funcs,
    engine_speedtree::units::funcs,
    engine_fallout_facegen::units::funcs,
    engine_fallout::units::funcs,
);
